import numpy as np
import torch
from transformers import AutoModel, AutoTokenizer

_DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
_TOKENIZER = AutoTokenizer.from_pretrained("bert-base-uncased")
_MODEL = AutoModel.from_pretrained("bert-base-uncased").to(_DEVICE)
_MODEL.eval()

FE_OUTPUT_STOCHASTIC = False


def feature_fn(train_inputs, train_labels, eval_inputs):
    def encode(records):
        outputs = []
        for start in range(0, len(records), 32):
            texts = [record["utterance"] for record in records[start:start + 32]]
            encoded = _TOKENIZER(
                texts,
                padding=True,
                truncation=True,
                max_length=128,
                return_tensors="pt",
            )
            encoded = {key: value.to(_DEVICE) for key, value in encoded.items()}
            with torch.no_grad():
                hidden = _MODEL(**encoded).last_hidden_state
                mask = encoded["attention_mask"].unsqueeze(-1).to(hidden.dtype)
                pooled = (hidden * mask).sum(dim=1) / mask.sum(dim=1)
            outputs.append(pooled.cpu().numpy().astype(np.float32, copy=False))
        if outputs:
            return np.concatenate(outputs, axis=0).astype(np.float32, copy=False)
        return np.empty((0, 768), dtype=np.float32)

    return encode(train_inputs), encode(eval_inputs)

import numpy as np
import torch
from transformers import AutoModel, AutoTokenizer
from sklearn.preprocessing import StandardScaler

FE_OUTPUT_STOCHASTIC = False

_TOKENIZER = None
_MODEL = None


def _get_model():
    global _TOKENIZER, _MODEL
    if _TOKENIZER is None:
        _TOKENIZER = AutoTokenizer.from_pretrained("microsoft/deberta-v3-large")
        _MODEL = AutoModel.from_pretrained(
            "microsoft/deberta-v3-large",
            output_hidden_states=True,
        )
        _MODEL.eval()
    return _TOKENIZER, _MODEL


def _make_pair(record):
    turns = [
        f"{speaker}: {text}"
        for text, speaker in zip(
            record["context"], record["context_speakers"]
        )
    ]
    utterance = f'{record["speaker"]}: {record["utterance"]}'
    return turns, utterance


def _fit_pair(tokenizer, record):
    turns, utterance = _make_pair(record)

    while True:
        context = " [SEP] ".join(turns)
        encoded = tokenizer(
            context,
            utterance,
            add_special_tokens=True,
            truncation=False,
        )
        if len(encoded["input_ids"]) <= 512 or not turns:
            break
        turns.pop(0)

    context = " [SEP] ".join(turns)
    if turns:
        encoded = tokenizer(
            context,
            utterance,
            add_special_tokens=True,
            truncation=False,
        )
        if len(encoded["input_ids"]) <= 512:
            return context, utterance

    return tokenizer(
        context,
        utterance,
        add_special_tokens=True,
        truncation="only_second",
        max_length=512,
    )


def _encode_records(records, tokenizer, model, device):
    pairs = []
    for record in records:
        pair = _fit_pair(tokenizer, record)
        if isinstance(pair, tuple):
            pairs.append(pair)
        else:
            pairs.append(pair)

    features = []
    with torch.inference_mode():
        for start in range(0, len(pairs), 8):
            batch = pairs[start:start + 8]
            if batch and isinstance(batch[0], tuple):
                first, second = zip(*batch)
                encoded = tokenizer(
                    list(first),
                    list(second),
                    padding=True,
                    truncation=False,
                    return_tensors="pt",
                )
            else:
                encoded = tokenizer.pad(
                    batch,
                    padding=True,
                    return_tensors="pt",
                )

            encoded = {
                key: value.to(device)
                for key, value in encoded.items()
            }
            outputs = model(
                **encoded,
                output_hidden_states=True,
            )
            hidden = torch.stack(
                outputs.hidden_states[21:25],
                dim=0,
            ).mean(dim=0)
            mask = encoded["attention_mask"].to(
                dtype=hidden.dtype
            ).unsqueeze(-1)
            pooled = (hidden * mask).sum(dim=1) / mask.sum(dim=1)
            features.append(pooled.float().cpu().numpy())

    if features:
        return np.concatenate(features, axis=0).astype(np.float32)
    return np.empty((0, 1024), dtype=np.float32)


def feature_fn(train_inputs, train_labels, eval_inputs):
    tokenizer, model = _get_model()

    if torch.cuda.is_available():
        device = torch.device("cuda", torch.cuda.current_device())
    else:
        device = torch.device("cpu")

    model.to(device=device, dtype=torch.float32)
    model.eval()

    train_features = _encode_records(
        train_inputs,
        tokenizer,
        model,
        device,
    )
    eval_features = _encode_records(
        eval_inputs,
        tokenizer,
        model,
        device,
    )

    scaler = StandardScaler(
        with_mean=True,
        with_std=True,
    )
    train_scaled = scaler.fit_transform(train_features)
    eval_scaled = scaler.transform(eval_features)

    return (
        np.asarray(train_scaled, dtype=np.float32),
        np.asarray(eval_scaled, dtype=np.float32),
    )

