_TOKEN_PATTERN = re.compile(r"\w+|[^\w\s]", re.UNICODE)


def _drop_words(utterance):
    matches = list(_TOKEN_PATTERN.finditer(utterance))
    word_indices = [i for i, match in enumerate(matches) if match.group().isalnum() or "_" in match.group()]

    if len(word_indices) <= 3:
        return utterance

    keep = {}
    for index in word_indices:
        keep[index] = random.random() >= 0.1

    if not any(keep.values()):
        keep[random.choice(word_indices)] = True

    parts = []
    position = 0
    for index, match in enumerate(matches):
        parts.append(utterance[position:match.start()])
        if index not in word_indices or keep.get(index, True):
            parts.append(match.group())
        position = match.end()
    parts.append(utterance[position:])

    return "".join(parts)


def aug_fn(train_data):
    augmented_train_data = list(train_data)
    for record, label in train_data:
        augmented_record = dict(record)
        augmented_record["utterance"] = _drop_words(record["utterance"])
        augmented_train_data.append((augmented_record, int(label)))
    return augmented_train_data

