_KEYBOARD_ROWS = ("qwertyuiop", "asdfghjkl", "zxcvbnm")
_KEY_NEIGHBORS = {}

for _row_index, _row in enumerate(_KEYBOARD_ROWS):
    for _col_index, _key in enumerate(_row):
        _neighbors = set()
        for _col_delta in (-1, 0, 1):
            _neighbor_col = _col_index + _col_delta
            if 0 <= _neighbor_col < len(_row):
                _neighbors.add(_row[_neighbor_col])
        for _adjacent_row in (_row_index - 1, _row_index + 1):
            if 0 <= _adjacent_row < len(_KEYBOARD_ROWS):
                _adjacent = _KEYBOARD_ROWS[_adjacent_row]
                for _neighbor_col in range(_col_index - 1, _col_index + 2):
                    if 0 <= _neighbor_col < len(_adjacent):
                        _neighbors.add(_adjacent[_neighbor_col])
        _neighbors.discard(_key)
        _KEY_NEIGHBORS[_key] = tuple(_neighbors)

_WORD_PATTERN = re.compile(r"[A-Za-z]{4,}")


def _noisy_word(word):
    if random.random() >= 0.05:
        return word

    chars = list(word)
    for _ in range(2):
        if not chars:
            break

        operation = random.randrange(3)

        if operation == 0:
            position = random.randrange(len(chars))
            base = chars[position].lower()
            neighbors = _KEY_NEIGHBORS.get(base, ())
            if neighbors:
                replacement = random.choice(neighbors)
                chars[position] = replacement.upper() if chars[position].isupper() else replacement
        elif operation == 1:
            del chars[random.randrange(len(chars))]
        elif len(chars) >= 2:
            position = random.randrange(len(chars) - 1)
            chars[position], chars[position + 1] = chars[position + 1], chars[position]

    return "".join(chars)


def _augment_utterance(utterance):
    return _WORD_PATTERN.sub(lambda match: _noisy_word(match.group(0)), utterance)


def aug_fn(train_data):
    augmented = list(train_data)
    for input_record, label in train_data:
        for _ in range(2):
            record = dict(input_record)
            record["utterance"] = _augment_utterance(input_record["utterance"])
            augmented.append((record, int(label)))
    return augmented


