from transformers import MarianMTModel, MarianTokenizer

AUG_OUTPUT_STOCHASTIC = True


def _translate(texts, tokenizer, model, device, sampled):
    if not texts:
        return []
    encoded = tokenizer(texts, return_tensors="pt", padding=True)
    encoded = {key: value.to(device) for key, value in encoded.items()}
    with torch.no_grad():
        generated = model.generate(
            **encoded,
            do_sample=sampled,
            top_p=0.9 if sampled else 1.0,
            num_beams=1 if sampled else 5,
        )
    return tokenizer.batch_decode(generated, skip_special_tokens=True)


def _round_trip(texts, pivot, models, device, sampled=True):
    if not texts:
        return []
    forward_tokenizer, forward_model, backward_tokenizer, backward_model = models[pivot]
    intermediates = _translate(
        texts,
        forward_tokenizer,
        forward_model,
        device,
        sampled,
    )
    return _translate(
        intermediates,
        backward_tokenizer,
        backward_model,
        device,
        sampled,
    )


def aug_fn(train_data):
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    pivots = ("de", "fr")
    models = {}

    for pivot in pivots:
        forward_name = "Helsinki-NLP/opus-mt-en-" + pivot
        backward_name = "Helsinki-NLP/opus-mt-" + pivot + "-en"
        forward_tokenizer = MarianTokenizer.from_pretrained(forward_name)
        forward_model = MarianMTModel.from_pretrained(forward_name).to(device)
        backward_tokenizer = MarianTokenizer.from_pretrained(backward_name)
        backward_model = MarianMTModel.from_pretrained(backward_name).to(device)
        models[pivot] = (
            forward_tokenizer,
            forward_model,
            backward_tokenizer,
            backward_model,
        )

    utterances = [record["utterance"] for record, _ in train_data]
    contexts = [
        sentence
        for record, _ in train_data
        for sentence in record["context"]
    ]

    translated_utterances = {
        pivot: _round_trip(utterances, pivot, models, device, sampled=True)
        for pivot in pivots
    }
    translated_contexts = {
        pivot: _round_trip(contexts, pivot, models, device, sampled=True)
        for pivot in pivots
    }

    beam_fallbacks = {}
    for index, original in enumerate(utterances):
        for pivot in pivots:
            if translated_utterances[pivot][index] == original:
                other_pivot = pivots[1] if pivot == pivots[0] else pivots[0]
                resampled = _round_trip(
                    [original],
                    pivot,
                    models,
                    device,
                    sampled=True,
                )[0]
                translated_utterances[pivot][index] = resampled
                if translated_utterances[pivot][index] == original:
                    if other_pivot not in beam_fallbacks:
                        beam_fallbacks[other_pivot] = {}
                    if original not in beam_fallbacks[other_pivot]:
                        beam_fallbacks[other_pivot][original] = _round_trip(
                            [original],
                            other_pivot,
                            models,
                            device,
                            sampled=False,
                        )[0]
                    translated_utterances[pivot][index] = beam_fallbacks[
                        other_pivot
                    ][original]

    augmented = list(train_data)
    context_offset = 0

    for index, (record, label) in enumerate(train_data):
        context_length = len(record["context"])
        copies = []

        for pivot in pivots:
            translated_record = dict(record)
            translated_record["utterance"] = translated_utterances[pivot][index]
            translated_record["context"] = translated_contexts[pivot][
                context_offset:context_offset + context_length
            ]
            translated_record["context_speakers"] = record["context_speakers"]
            copies.append((translated_record, int(label)))

        augmented.extend(copies)
        context_offset += context_length

    return augmented

