def _format_text(text, lowercase):
    text = text.replace("“", '"').replace("”", '"').replace("„", '"')
    text = text.replace("‘", "'").replace("’", "'").replace("‚", "'")
    text = " ".join(text.split())

    if lowercase:
        return text.lower()

    lowered = text.lower()
    for index, character in enumerate(lowered):
        if character.isalpha():
            return lowered[:index] + character.upper() + lowered[index + 1:]
    return lowered


def _uppercase_first_word(text):
    for index, character in enumerate(text):
        if character.isalpha():
            end = index
            while end < len(text) and text[end].isalpha():
                end += 1
            return text[:index] + text[index:end].upper() + text[end:]
    return text


