        transformed_context = [
            _format_text(sentence, lowercase)
            for sentence in record["context"]
        ]

        if (
            transformed_utterance == record["utterance"]
            and transformed_context == record["context"]
        ):
            lowercase = not lowercase
            transformed_utterance = _format_text(record["utterance"], lowercase)
            transformed_context = [
