def _mapping_for(names, pool):
    targets = random.sample(pool, len(names))
    bad = [i for i, name in enumerate(names) if targets[i] == name]

    if len(bad) > 1:
        rotated = [targets[i] for i in bad]
        rotated = rotated[1:] + rotated[:1]
        for i, target in zip(bad, rotated):
            targets[i] = target
    elif len(bad) == 1:
