import torch
from transformers import MarianMTModel, MarianTokenizer

AUG_OUTPUT_STOCHASTIC = True

_BATCH_SIZE = 64
_MAX_LENGTH = 512
_PIVOTS = ("de", "fr")
_MODELS = {}


def _device():
    if torch.cuda.is_available():
        return torch.device("cuda", torch.cuda.current_device())
    return torch.device("cpu")


def _get_model(src, dst):
    key = (src, dst)
    if key not in _MODELS:
        name = f"Helsinki-NLP/opus-mt-{src}-{dst}"
        tokenizer = MarianTokenizer.from_pretrained(name)
        model = MarianMTModel.from_pretrained(name)
        model.to(_device())
        model.eval()
        _MODELS[key] = (tokenizer, model)
    return _MODELS[key]


def _translate(texts, src, dst, do_sample, num_beams=1):
    tokenizer, model = _get_model(src, dst)
    device = _device()
    outputs = []

    for start in range(0, len(texts), _BATCH_SIZE):
        batch = texts[start:start + _BATCH_SIZE]
        encoded = tokenizer(
            batch,
            return_tensors="pt",
            padding=True,
            truncation=True,
            max_length=_MAX_LENGTH,
        )
        encoded = {key: value.to(device) for key, value in encoded.items()}

        generation_args = {
            "max_length": _MAX_LENGTH,
            "num_beams": num_beams,
            "do_sample": do_sample,
        }
        if do_sample:
            generation_args["top_p"] = 0.9

        with torch.inference_mode():
            generated = model.generate(**encoded, **generation_args)

        outputs.extend(tokenizer.batch_decode(generated, skip_special_tokens=True))

    return outputs


def _round_trip(texts, pivot, do_sample, num_beams=1):
    forward = _translate(texts, "en", pivot, do_sample, num_beams)
    return _translate(forward, pivot, "en", do_sample, num_beams)


def _normalized(text):
    return " ".join(text.split()).casefold()


def aug_fn(train_data):
    augmented = list(train_data)

    for input_record, label in train_data:
        source_texts = [input_record["utterance"]] + list(input_record["context"])
        pivot_outputs = {}

        for pivot in _PIVOTS:
            outputs = _round_trip(source_texts, pivot, True)
            identical = [
                _normalized(output) == _normalized(source)
                for output, source in zip(outputs, source_texts)
            ]

            if any(identical):
                resampled = _round_trip(source_texts, pivot, True)
                for index, is_identical in enumerate(identical):
                    if is_identical:
                        outputs[index] = resampled[index]

            pivot_outputs[pivot] = outputs

        for pivot, other_pivot in (("de", "fr"), ("fr", "de")):
            outputs = pivot_outputs[pivot]
            fallback_indices = [
                index
                for index, (output, source) in enumerate(zip(outputs, source_texts))
                if _normalized(output) == _normalized(source)
            ]

            if fallback_indices:
                beam_outputs = _round_trip(source_texts, other_pivot, False, num_beams=5)
                for index in fallback_indices:
                    outputs[index] = beam_outputs[index]

            record = dict(input_record)
            record["utterance"] = outputs[0]
            record["context"] = outputs[1:]
            augmented.append((record, int(label)))

    return augmented
